import React from 'react';
import './App.css';
import './Moviechart/Moviechart.css'
import MovieChart from './Moviechart/Moviechart';
import Booking from './movieboard-app/Booking';
import { BrowserRouter as Router, Route, Routes} from 'react-router-dom';




const App = () => {
  return (
    <Router>
    <div className="App">
      <h1 className='movieline'>무비차트</h1>
      <Routes>
        <Route path="/" exact component={MovieChart}/>
        <Route path="/movieboard-app" component={Booking}/>
      </Routes>
    </div>
    </Router>
  );

  
}

export default App;
